#include "test.hpp"
#include "mspa/mspa.hpp"
using namespace mspa;
static RegistrySnapshot registry(){RegistryBuilder b;PredicateSchema s{};s.id=PredicateId(1);s.name_space=NamespaceId(1);s.required_roles={"actor"};s.default_relevance=0.9f;s.default_consequence=-0.7f;s.intentionality=1.0f;s.agency_role="actor";require(b.add_predicate(s),"predicate");require(b.add_action_type(ActionTypeId(1),"eat"),"action1");require(b.add_action_type(ActionTypeId(2),"wait"),"action2");return b.publish();}
int main(){RuntimeConfig c{};c.runtime_id=RuntimeId(1);c.world_id=WorldId(10);c.time_domain={TimeDomainId(1),{60,1}};c.seed_root=123;auto rr=Runtime::create(c,registry());require(rr,"runtime");auto r=std::move(*rr.value_if());AgentId a{c.world_id,1};AgentInit init{};init.personality.boldness=0.8f;init.values.push_back({ConceptId(100),0.9f});require(r->create_agent(a,init,PsychTime(1)),"agent create");ObserveInput ob{};ob.agent=a;ob.proposition.predicate=PredicateId(1);ob.proposition.name_space=NamespaceId(1);ob.proposition.arguments.push_back({"actor","enemy"});ob.time.process_time=PsychTime(2);auto ores=r->observe(ob);require(ores&&ores.value_if()->decision_recommended,"observe");require(!r->agents().find(a)->beliefs.empty(),"belief after observe");ActionOption eat{};eat.type=ActionTypeId(1);eat.instance=ActionInstanceId(1);eat.continuity=ActionContinuityKey(1);eat.actor=a;eat.cost=0.2f;eat.expected_effects.push_back({EffectChannel::Need,ConceptId(200),{},1.0f,"sated"});ActionOption wait{};wait.type=ActionTypeId(2);wait.instance=ActionInstanceId(2);wait.continuity=ActionContinuityKey(2);wait.actor=a;wait.cost=0.1f;DecisionContext dc{};dc.needs.push_back({ConceptId(200),1.0f});auto dec=r->decide(a,{eat,wait},dc,PsychTime(3));require(dec&&dec.value_if()->selected_action==eat.instance,"needs affect decision");ReportInput rep{};rep.agent=a;rep.action_type=eat.type;rep.success=true;rep.process_time=PsychTime(4);rep.context_tags={"hungry"};rep.outcome_tags={"sated"};require(r->report(rep),"report");require(!r->agents().find(a)->learned_expectations.empty(),"learning after report");auto adv=r->advance_to(a,PsychTime(100));require(adv&&adv.value_if()->state_changed,"advance");ObserveBatchItem x{};x.input_sequence=1;x.input=ob;x.input.time.process_time=PsychTime(101);ObserveBatchItem y=x;y.input_sequence=1;y.input.time.process_time=PsychTime(102);require(!r->observe_batch({x,y}),"duplicate batch sequence rejected");AgentId b{c.world_id,2};require(r->create_agent(b,AgentInit{},PsychTime(1)),"agent b");ReportInput rb{};rb.agent=b;rb.action_type=ActionTypeId(2);rb.success=true;rb.process_time=PsychTime(2);rb.relationship_impacts.push_back({a,{0,0.5f,0,0}});require(r->report(rb),"relationship report");require(!r->remove_agent(a,PsychTime(102),RemovePolicy::ValidateNoReferences),"remove ref validation");require(r->remove_agent(a,PsychTime(102),RemovePolicy::ForgetRuntimeOnly),"forced remove");require(!r->has_agent(a),"removed");std::cout<<"runtime ok\n";}
